import requests
from bs4 import BeautifulSoup
import datetime

def obtener_datos_reddit(url):
    """Obtiene datos de Reddit usando la API 'Subreddit' y los filtra por nombres de usuario."""
    try:
        url = url.replace('https://', '')
        headers = {'User-Agent': 'Python Reddit Tracker'}
        response = requests.get(url, headers=headers)
        response.raise_for_status()
        soup = BeautifulSoup(response.content, 'html.parser')

        # Encuentra todos los posts (normalmente se encuentran en el subm complicado)
        posts = soup.find_all('div', class_='r-post')

        # Recopila los IDs de los posts
        post_ids = {}
        for post in posts:
            try:
                post_id = post.find('div', class_='r-post-id').get('data-subreddit-id')
                if post_id:
                    post_ids[post_id] = post.find('div', class_='r-post-link').find('a').get('href')
            except:
                pass

        # Recopila los datos del usuario (nombre de usuario)
        user_data = {}
        for post_id in post_ids:
            try:
                user_url = f'https://www.reddit.com/r/{post_id}'
                response = requests.get(user_url)
                response.raise_for_status()
                soup = BeautifulSoup(response.content, 'html.parser')

                # Encuentra la etiqueta de 'id' de la sección de perfil. Necesitamos el 'title' para el nombre de usuario.
                profile_id = soup.find('a', class_='r-post-profile-link').get('href')
                if profile_id:
                    user_data[post_id] = profile_id
            except:
                pass
        return user_data

    except requests.exceptions.RequestException as e:
        print(f"Error al obtener datos de Reddit: {e}")
        return None

